function restore(previous: Record<string, unknown>, next: Record<string, unknown>) {
  const sourcing = object(previous.sourcing)
  const po = object(previous.po)
  return {
    ...next,
    attachments: previous.attachments ?? next.attachments ?? [],
    sourcing:
      next.sourcing == null
