    const value = await state.read(request, "preferences", (stored, authority) => authority.principalRef === context.binding.principalRef && authority.accessRevision === context.binding.accessRevision && authority.policyVersion === context.binding.policyVersion ? stored.preferences[archiveKey(ref)] : undefined)
    const archived = value.status === "ok" ? readArchive(value.value) : undefined
    return archived && digestSfValue(archived.evidence) === digestSfValue(ref) ? archived : undefined
  }
  // The router asks for continuity immediately after this producer resolves history.
  // Retain that original observation, not an authorization decision: proveContinuity
  // must still reread the archive and fence current material and authority below.
  const historicalProofs = new WeakMap<TrustedDomainContext, Map<string, ArchivedSource>>()
  const historyKey = (original: BusinessEvidenceRef, current: BusinessEvidenceRef) => digestSfValue({ original, current })
  const physicalContinuity = async (archived: ArchivedSource, currentRef: RecordEvidence, context: TrustedDomainContext) => {
    const request = host.requestFor(context)
    const selected = await input.individual.resolveForPreparation(currentRef.refId, context)
    if (!request || selected.status !== "ok" || digestSfValue(selected.value.evidence) !== digestSfValue(currentRef) || !await host.revalidate(context)) return false
    const current = await host.persistence.transaction("procurement", async (snapshot) => {
      const principal = await host.authenticate(request, { surface: "procurement", roleMap: roleMap(snapshot, "procurement") })
      if (!principal || principal.id !== context.binding.principalRef || principal.id.startsWith("local:")) return { commit: false, value: false }
      const roles = principal.roles.filter((entry) => entry.surface === "procurement").map((entry) => entry.role)
      const selector = object(selected.value.scope.selector)
      if (selector.roleMapDigest !== digestSfValue(roleMap(snapshot, "procurement")) || digestSfValue(selector.roles) !== digestSfValue(roles) || selector.canWrite !== (principal.canWrite && roles.some((role) => role !== "viewer")) || !input.individual.isCurrent(snapshot, currentRef)) return { commit: false, value: false }
      const original = Object.values(snapshot.sfSources?.scopes ?? {}).filter((entry) => entry.incarnation === archived.evidence.target.incarnation && digestSfValue(entry.scope) === digestSfValue(archived.scope))
      const present = Object.values(snapshot.sfSources?.scopes ?? {}).filter((entry) => entry.alive && entry.incarnation === currentRef.target.incarnation && entry.version === currentRef.target.version && digestSfValue(entry.scope) === digestSfValue(selected.value.scope))
      const physical = snapshot.sfSources?.records[JSON.stringify([archived.evidence.target.recordType, archived.evidence.target.recordId])]
      return { commit: false, value: original.length === 1 && present.length === 1 && original[0]!.sourceIncarnation === archived.physicalIncarnation && present[0]!.sourceIncarnation === archived.physicalIncarnation && physical?.alive === true && physical.incarnation === archived.physicalIncarnation }
    }, { signal: request.signal })
    return current && await host.revalidate(context)
  }
  const resolveHistoricalSource = async (ref: RecordEvidence, context: TrustedDomainContext): Promise<BusinessEvidenceResolution | undefined> => {
    const unavailable = (): BusinessEvidenceResolution => ({ state: "unavailable", ref, accessRevision: context.binding.accessRevision, checkedAt: input.now() })
    if (ref.target.recordType !== "procurement-request" || !ref.refId.startsWith("sf-procurement:")) return undefined
    const archived = await readOriginal(ref, context)
    if (!archived) return undefined
    const issued = await input.individual.issueForActor(ref.target, context)
    if (issued.status !== "ok") return unavailable()
    if (digestSfValue(issued.value) === digestSfValue(ref)) return undefined
    if (!await physicalContinuity(archived, issued.value, context)) return unavailable()
    const currentProjection = await input.port.read({ requestRef: issued.value.refId }, context)
    if (currentProjection.status !== "ok") return unavailable()
    const differences: NonNullable<BusinessEvidenceResolution["differences"]>[number][] = []
    for (const previous of archived.projection.values.filter((value) => value.id !== "ageDays")) {
      const currentValue = currentProjection.value.values.find((value) => value.id === previous.id)
      if (!currentValue) return unavailable()
      if (previous.value !== currentValue.value) differences.push({ field: previous.id, before: previous.value, after: currentValue.value })
      if (previous.currency !== currentValue.currency) differences.push({ field: `${previous.id}.currency`, before: previous.currency ?? null, after: currentValue.currency ?? null })
    }
    if (archived.projection.context.currency !== currentProjection.value.context.currency) differences.push({ field: "currency", before: archived.projection.context.currency, after: currentProjection.value.context.currency })
    const again = await readOriginal(ref, context)
    const issuedAgain = await input.individual.issueForActor(ref.target, context)
    if (!again || digestSfValue(again) !== digestSfValue(archived) || issuedAgain.status !== "ok" || digestSfValue(issuedAgain.value) !== digestSfValue(issued.value) || !await physicalContinuity(archived, issued.value, context) || !await host.revalidate(context)) return unavailable()
    const projection: DomainProjection = { ...structuredClone(archived.projection), context: { ...structuredClone(archived.projection.context), principalRef: context.binding.principalRef, accessRevision: context.binding.accessRevision, policyVersion: context.binding.policyVersion } }
    const proofs = historicalProofs.get(context) ?? new Map<string, ArchivedSource>()
    proofs.set(historyKey(ref, issued.value), structuredClone(archived))
    if (proofs.size > 256) proofs.delete(proofs.keys().next().value!)
    historicalProofs.set(context, proofs)
    return { state: "historical", ref, currentRef: issued.value, authorizedProjection: projection, differences, accessRevision: context.binding.accessRevision, checkedAt: input.now() }
  }
  const resolveReceipt = async (ref: Extract<BusinessEvidenceRef, { kind: "receipt" }>, context: TrustedDomainContext): Promise<BusinessEvidenceResolution> => {
    const unavailable = (): BusinessEvidenceResolution => ({ state: "unavailable", ref, accessRevision: context.binding.accessRevision, checkedAt: input.now() })
    const request = host.requestFor(context)
    if (!request || !ref.refId.startsWith("sf-procurement-receipt:") || !await host.revalidate(context)) return unavailable()
    const read = async () => {
      const cases = await state.read(request, "cases", (stored, authority) => authority.principalRef === context.binding.principalRef && authority.accessRevision === context.binding.accessRevision && authority.policyVersion === context.binding.policyVersion ? Object.values(stored.cases).filter((value) => value.participants.includes(context.binding.principalRef) && (context.kind === "ui" || value.id === context.binding.caseId && value.incarnation === context.binding.caseIncarnation && value.version === context.binding.caseVersion)).flatMap((decision) => decision.sourceRefs.some((source) => digestSfValue(source) === digestSfValue(ref)) ? decision.preparedChanges.filter((change) => change.receipt?.id === ref.target.receiptId).map((change) => ({ decision, change })) : []) : [])
      if (cases.status !== "ok" || cases.value.length !== 1) return undefined
      const receipts = await state.read(request, "receipts", (stored, authority) => authority.principalRef === context.binding.principalRef && authority.accessRevision === context.binding.accessRevision && authority.policyVersion === context.binding.policyVersion ? stored.receipts[ref.target.receiptId] : undefined)
      if (receipts.status !== "ok" || !receipts.value) return undefined
      const candidate = cases.value[0]!
      const receipt = receipts.value
      const change = candidate.change
      if (digestSfValue(change.receipt) !== digestSfValue(receipt) || receipt.surface !== "procurement" || ref.target.surface !== receipt.surface || receipt.targetIncarnation !== ref.target.targetIncarnation || receipt.commandDigest !== ref.target.commandDigest || receipt.idempotencyKey !== ref.target.idempotencyKey || receipt.version !== ref.target.version || change.target.surface !== "procurement" || change.target.incarnation !== receipt.targetIncarnation || change.operation.commandDigest !== receipt.commandDigest || change.idempotencyKey !== receipt.idempotencyKey || change.state === "planned" || receipt.result.ok !== ["applied", "awaiting-approval"].includes(change.state)) return undefined
      const source = change.operation.preview.values.flatMap((value) => value.sourceRefs)[0]
      if (!source || source.kind !== "record") return undefined
      const archived = await readOriginal(source, context)
      if (!archived) return undefined
      const currentSource = await input.individual.issueForActor(source.target, context)
      if (currentSource.status !== "ok" || !await physicalContinuity(archived, currentSource.value, context) || !await host.revalidate(context)) return undefined
      const selected = await input.individual.resolve(currentSource.value.refId, context)
      return selected.status === "ok" ? { ...candidate, receipt, currentSource: currentSource.value, context: selected.value.context } : undefined
    }
    const value = await read()
    if (!value) return unavailable()
    const projection: DomainProjection = { context: value.context, version: value.receipt.version, engineVersion: "procurement-receipt-v1", components: [], missing: [], values: [
      { id: "applicationStatus", value: value.change.state, period: value.context.period, granularity: "record", sourceRefs: [ref], drilldown: ref, evidenceState: "confirmed" },
      { id: "applicationVersion", value: value.receipt.version, period: value.context.period, granularity: "record", sourceRefs: [ref], drilldown: ref, evidenceState: "confirmed" },
    ] }
    const again = await read()
    if (!again || digestSfValue(again) !== digestSfValue(value) || request.signal.aborted || !await host.revalidate(context)) return unavailable()
    return { state: "fresh", ref, currentRef: ref, authorizedProjection: projection, accessRevision: context.binding.accessRevision, checkedAt: input.now() }
  }
  const resolveEvidence = async (ref: BusinessEvidenceRef, context: TrustedDomainContext): Promise<BusinessEvidenceResolution | undefined> => {
    if ((ref.kind !== "record" && ref.kind !== "receipt") || ref.target.surface !== "procurement") return undefined
    try {
      if (ref.schema !== "sf-evidence-v1" || ref.refDigest !== digestSfEvidenceRef(ref) || ref.installationId !== context.binding.installationId || ref.projectId !== context.binding.projectId || !await host.revalidate(context)) return { state: "unavailable", ref, accessRevision: context.binding.accessRevision, checkedAt: input.now() }
      return ref.kind === "record" ? await resolveHistoricalSource(ref, context) : await resolveReceipt(ref, context)
    } catch { return { state: "unavailable", ref, accessRevision: context.binding.accessRevision, checkedAt: input.now() } }
  }
  const proveContinuity = async (original: BusinessEvidenceRef, currentRef: BusinessEvidenceRef, context: TrustedDomainContext) => {
    if (original.kind !== "record" || currentRef.kind !== "record" || original.target.surface !== "procurement" || original.target.recordType !== "procurement-request" || !original.refId.startsWith("sf-procurement:")) return undefined
    const observed = historicalProofs.get(context)?.get(historyKey(original, currentRef))
    if (!observed || !await host.revalidate(context)) return false
    const archived = await readOriginal(original, context)
    if (!archived || digestSfValue(archived) !== digestSfValue(observed)) return false
    // physicalContinuity resolves the current actor's scope again and uses isCurrent,
    // which compares the canonical material digest and revision as well as identity.
    return await physicalContinuity(archived, currentRef, context) && await host.revalidate(context)
  }
  return { prepareChanges: mutations.prepareChanges, prepareDomainCommands, reviewChange, apply, recover, authorizeReceiptTarget, resolveEvidence, proveContinuity, dispose: () => reviews.clear() }
}

function sameApplicationAuthority(authority: SfStateAuthority, context: TrustedDomainContext) {
  return authority.principalRef === context.binding.principalRef && authority.accessRevision === context.binding.accessRevision && authority.policyVersion === context.binding.policyVersion
}

function applicationIntentKey(request: ApplyRequest) {
  return `sf:c12:application:${digestSfValue({ caseId: request.caseRef.id, caseIncarnation: request.caseRef.incarnation, choiceId: request.choiceId, changeId: request.changeId })}`
}

function applicationIntentEntries(state: Readonly<SfProductState>, request: ApplyRequest) {
  // A change already attempted by any principal cannot become a fresh dispatch.
  return Object.entries(state.transactions).filter(([key, transaction]) => key === JSON.stringify([transaction.principalRef, "cases", request.caseRef.id, applicationIntentKey(request)])).map(([, transaction]) => transaction)
}

function applicationIntent(scope: ApplicationScope, admitted: AdmittedApply, commandId: string): ApplicationIntent {
  return { schema: "sf-c12-application-intent-v1", installationId: scope.context.binding.installationId, projectId: scope.context.binding.projectId, principalRef: scope.context.binding.principalRef, admitted: structuredClone(admitted), commandId, changeDigest: digestSfValue({ ...scope.change, state: "planned", receipt: null }), choiceDigest: digestSfValue(scope.decision.choices.find((choice) => choice.id === scope.change.choiceId)), physicalIncarnation: scope.physicalIncarnation }
}

function readApplicationIntent(state: Readonly<SfProductState>, scope: ApplicationScope): ApplicationIntent | undefined {
  const entries = applicationIntentEntries(state, scope.request)
  if (entries.length !== 1) return undefined
  const transaction = entries[0]!
  const record = object(transaction.value)
  const admitted = object(record.admitted)
  const ref = object(admitted.caseRef)
  if (ref.id !== scope.decision.id || ref.incarnation !== scope.decision.incarnation || !Number.isSafeInteger(ref.version) || Number(ref.version) < 1 || Number(ref.version) > scope.decision.version || admitted.changeId !== scope.change.id || admitted.choiceId !== scope.change.choiceId || typeof admitted.reviewDigest !== "string" || !isReviewDigest(admitted.reviewDigest) || typeof record.commandId !== "string" || !record.commandId.trim()) return undefined
  const expected = applicationIntent(scope, { caseRef: { id: scope.decision.id, incarnation: scope.decision.incarnation, version: Number(ref.version) }, choiceId: scope.change.choiceId, changeId: scope.change.id, reviewDigest: admitted.reviewDigest }, record.commandId)
  return transaction.namespace === "cases" && transaction.scopeDigest === digestSfValue(["cases"]) && transaction.incarnation === state.incarnation && transaction.principalRef === scope.context.binding.principalRef && transaction.targetRef === scope.decision.id && transaction.targetIncarnation === scope.decision.incarnation && transaction.commandDigest === digestSfValue(expected) && digestSfValue(record) === digestSfValue(expected) ? expected : undefined
}

function stableProjection(value: DomainProjection) {
  // Observation clocks do not change the material source. Keep the immutable original
  // bytes and all authority, scope and source digests; normalize only this comparison.
  const source = (ref: DomainProjection["context"]["sourceRefs"][number]) => {
    const { observedAt: _observedAt, ...material } = ref
    return material
  }
  return { ...value, context: { ...value.context, sourceRefs: value.context.sourceRefs.map(source) }, components: value.components.map((component) => ({ ...component, sourceRefs: component.sourceRefs.map(source) })), values: value.values.filter((field) => field.id !== "ageDays") }
}

function readArchive(value: unknown): ArchivedSource | undefined {
  const stored = object(value)
  if (stored.schema !== "sf-procurement-evidence-v1" || typeof stored.physicalIncarnation !== "string" || !stored.physicalIncarnation || typeof stored.proofDigest !== "string") return undefined
  const projection = decodeSfOperationOutput("sf_request_read", stored.projection)
  if (!projection.ok || stored.projectionDigest !== digestSfValue(projection.value)) return undefined
  const evidence = projection.value.values[0]?.sourceRefs[0]
  if (!evidence || evidence.kind !== "record" || evidence.target.surface !== "procurement" || evidence.target.recordType !== "procurement-request" || evidence.refDigest !== digestSfEvidenceRef(evidence) || digestSfValue(stored.evidence) !== digestSfValue(evidence) || projection.value.values.some((field) => field.sourceRefs.length !== 1 || digestSfValue(field.sourceRefs[0]) !== digestSfValue(evidence))) return undefined
  const scope = object(stored.scope)
  if (typeof scope.principalRef !== "string" || typeof scope.accessRevision !== "string" || typeof scope.policyVersion !== "string" || typeof scope.recordType !== "string" || typeof scope.recordId !== "string" || scope.recordType !== evidence.target.recordType || scope.recordId !== evidence.target.recordId || projection.value.context.principalRef !== scope.principalRef || projection.value.context.accessRevision !== scope.accessRevision || projection.value.context.policyVersion !== scope.policyVersion) return undefined
  const material = { schema: "sf-procurement-evidence-v1" as const, evidence, projection: projection.value, scope: { principalRef: scope.principalRef, accessRevision: scope.accessRevision, policyVersion: scope.policyVersion, recordType: scope.recordType, recordId: scope.recordId, selector: scope.selector }, physicalIncarnation: stored.physicalIncarnation, projectionDigest: digestSfValue(projection.value) }
  return stored.proofDigest === digestSfValue(material) ? { ...material, proofDigest: stored.proofDigest } : undefined
}

import { digestSfValue } from "../contracts/canonical.ts"
import { roleMap } from "../../runtime/admin.ts"
import { object, rows, text } from "../../runtime/contract.ts"
import type { Actor, Command, Environment, Snapshot } from "../../runtime/contract.ts"
import { domain } from "../../runtime/procurement.ts"
import { validatePR } from "../../src/form.ts"
import { approvalDecision } from "../../src/procurement-screen.ts"
import type { RequestView } from "../../src/procurement-screen.ts"
import type { BusinessEvidenceRef } from "../contracts/business-context.ts"
import type { DomainProjection } from "../contracts/context.ts"
import type { CommercialComparison } from "../contracts/outputs.ts"
import type { DomainPortHost, PortResult, ProcurementPort } from "../contracts/ports.ts"
import type { TrustedDomainContext } from "../contracts/sf-execution.ts"
import { createProcurementReadonlySourceResolver } from "./scenario-producer.ts"

/** Read-only material for the purchase dossier; it never prepares or applies a command. */
export function createProcurementDecisionPreparation(port: ProcurementPort) {
  return async (requestRef: string, binding: TrustedDomainContext): Promise<PortResult<{ request: DomainProjection; comparison: CommercialComparison | null; limitations: readonly string[] }>> => {
    const request = await port.read({ requestRef }, binding)
    if (request.status !== "ok") return request
    const comparison = await port.compareSourcing({ requestRef, proposalRefs: [], criteria: [] }, binding)
    if (comparison.status !== "ok" && comparison.status !== "needs-input") return comparison
    const current = await port.read({ requestRef }, binding)
    if (current.status !== "ok") return current
    const stable = (value: DomainProjection) => ({ ...value, values: value.values.filter((item) => item.id !== "ageDays") })
    if (digestSfValue(stable(current.value)) !== digestSfValue(stable(request.value))) return { status: "stale", reason: "Request changed during preparation" }
    if (comparison.status === "ok") {
      const evidence = request.value.values.flatMap((value) => value.sourceRefs)
      if (comparison.value.requestVersion !== request.value.version || !comparison.value.sourceRefs.length || comparison.value.sourceRefs.some((ref) => !evidence.some((item) => item.refDigest === ref.refDigest))) return { status: "stale", reason: "Comparison source changed" }
    }
    return { status: "ok", value: { request: current.value, comparison: comparison.status === "ok" ? comparison.value : null, limitations: comparison.status === "needs-input" ? [comparison.reason] : [] } }
  }
}

export type ProcurementApprovalAction =
  | { kind: "save-estimate"; amount: number }
  | { kind: "submit-current"; amount: number }
  | { kind: "approve-submitted"; amount: number; holderId: string | null; comment: string }
  | { kind: "reject-submitted"; amount: number; holderId: string | null; reason: string }

export type ProcurementApprovalReview = {
  kind: "procurement-pr-review-v1"
  source: Extract<BusinessEvidenceRef, { kind: "record" }>
  domainVersion: number
  stage: string
  amount: number | null
  currency: string
  submittedAmount: number | null
  submittedCurrency: string | null
  holderId: string | null
  allowedActions: readonly ProcurementApprovalAction["kind"][]
  authorityDigest: string
  recordDigest: string
  policyDigest: string
}

export type ProcurementApprovalPlan = {
  kind: "procurement-pr-lifecycle-v1"
  command: Command
  review: ProcurementApprovalReview
  action: ProcurementApprovalAction
  requiresExplicitAction: true
  approvalGranted: false
  receipt: null
}

export type ProcurementApprovalAdmission = {
  // The host calls this synchronously inside the canonical command transaction,
  // after fresh authentication and immediately before its single domain.execute.
  current: (snapshot: Snapshot, actor: Actor, command: Command, environment: Environment) => PortResult<true>
  finish: () => void
}

/** Read-only adaptation to the existing Requests form commands, never a C12 Apply or an approval grant. */
export function createProcurementApprovalLifecycle(input: { host: DomainPortHost }) {
  const sources = createProcurementReadonlySourceResolver(input)
  const snapshotReview = (snapshot: Snapshot, actor: Actor, environment: Environment, evidence: ProcurementApprovalReview["source"], binding: TrustedDomainContext): PortResult<{ review: ProcurementApprovalReview; requisition: Record<string, unknown> }> => {
    if (binding.kind !== "ui" || actor.id !== binding.binding.principalRef || actor.id.startsWith("local:") || !actor.canWrite || !actor.roles.some((role) => role !== "viewer") || evidence.installationId !== binding.binding.installationId || evidence.projectId !== binding.binding.projectId) return { status: "denied", reason: "current-authority-unavailable" }
    const scopes = Object.values(snapshot.sfSources?.scopes ?? {}).filter((entry) => entry.alive && entry.incarnation === evidence.target.incarnation)
    if (scopes.length !== 1) return { status: "stale", reason: "requisition-source-changed" }
    const scope = scopes[0]!.scope
    const selected = object(scope.selector)
    const selector = { kind: "procurement-record-v1", roles: actor.roles, canWrite: actor.canWrite, roleMapDigest: digestSfValue(roleMap(snapshot, "procurement")), fields: selected.fields, period: selected.period, currency: selected.currency }
    if (scope.principalRef !== binding.binding.principalRef || scope.accessRevision !== binding.binding.accessRevision || scope.policyVersion !== binding.binding.policyVersion || scope.recordType !== "procurement-request" || scope.recordId !== evidence.target.recordId || digestSfValue(selector) !== digestSfValue(scope.selector)) return { status: "denied", reason: "current-authority-unavailable" }
    if (!sources.isCurrent(snapshot, evidence)) return { status: "stale", reason: "requisition-source-changed" }
    if (!Number.isFinite(Date.parse(environment.at))) return { status: "unavailable", reason: "observation-time-unavailable" }
    const view = domain.view(snapshot, actor, environment)
    const current = rows(view.data.requests).find((item) => item.number === evidence.target.recordId)
    const version = snapshot.versions[`requests:${evidence.target.recordId}`]?.version
    if (!current || !Number.isSafeInteger(version) || version === undefined || version < 0) return { status: "unavailable", reason: "requisition-unavailable" }
    const settings = object(object(snapshot.data.store).settings)
    const stage = text(current.status)
    const approval = object(current.prApproval)
    const holder = stage === "pr_pending" ? rows(approval.steps).find((step) => step.status === "pending") : undefined
    const currency = stage === "pr_pending" ? text(current.prApprovalBaseCurrency) : text(settings.currency)
    if (!/^[A-Z]{3}$/.test(currency)) return { status: "needs-input", reason: "requisition-currency-unavailable" }
    const draft = stage === "draft" || stage === "pr_rejected"
    const creator = current.createdBy === actor.id
    const admin = actor.roles.includes("admin")
    const decision = stage === "pr_pending" && approvalDecision(current as RequestView, actor, settings.blockSelfApproval === true).allowed
    const allowedActions: ProcurementApprovalAction["kind"][] = [
      ...(draft && (creator || admin) ? ["save-estimate" as const] : []),
      ...(draft && (creator || admin || actor.roles.includes("requester")) ? ["submit-current" as const] : []),
      ...(decision ? ["approve-submitted" as const, "reject-submitted" as const] : []),
    ]
    // Procurement authorization uses id/canWrite/roles. Other surfaces' assignments
    // must not make HTTP and readonly review produce different authority digests.
    const authorityActor: Actor = { id: actor.id, canWrite: actor.canWrite, roles: actor.roles, assigned: [], domains: [] }
    const review: ProcurementApprovalReview = {
      kind: "procurement-pr-review-v1", source: evidence, domainVersion: version, stage,
      amount: finiteApprovalAmount(object(current.pr).estAmount), currency,
      submittedAmount: finiteApprovalAmount(approval.amount), submittedCurrency: text(current.prApprovalBaseCurrency) || null,
      holderId: typeof holder?.holderId === "string" ? holder.holderId : null, allowedActions,
      authorityDigest: digestSfValue({ installationId: binding.binding.installationId, projectId: binding.binding.projectId, principalRef: actor.id, accessRevision: binding.binding.accessRevision, policyVersion: binding.binding.policyVersion, actor: authorityActor }),
      recordDigest: digestSfValue(current), policyDigest: digestSfValue({ settings, roleMap: roleMap(snapshot, "procurement") }),
    }
    return { status: "ok", value: { review, requisition: object(current.pr) } }
  }
  const read = async (sourceRef: string, binding: TrustedDomainContext) => {
    // A native/model invocation cannot turn a proposal into a human command plan.
    const request = input.host.requestFor(binding)
    if (binding.kind !== "ui" || !request || request.signal.aborted || !await input.host.revalidate(binding) || input.host.requestFor(binding) !== request) return { status: "denied" as const, reason: "current-authority-unavailable" }
    const source = await sources.resolveSource(sourceRef, binding)
    if (source.status !== "ok") return source
    const environment = await input.host.environment(request)
    if (!Number.isFinite(Date.parse(environment.at))) return { status: "unavailable" as const, reason: "observation-time-unavailable" }
    const snapshotRead = () => input.host.persistence.transaction<PortResult<{ review: ProcurementApprovalReview; requisition: Record<string, unknown> }>>("procurement", async (snapshot) => {
      const principal = await input.host.authenticate(request, { surface: "procurement", roleMap: roleMap(snapshot, "procurement") })
      if (!principal || principal.id !== binding.binding.principalRef || principal.id.startsWith("local:") || !principal.canWrite || request.signal.aborted) return { commit: false, value: { status: "denied", reason: "current-authority-unavailable" } }
      const roles = principal.roles.filter((role) => role.surface === "procurement").map((role) => role.role)
      const actor: Actor = { id: principal.id, canWrite: roles.some((role) => role !== "viewer"), roles, assigned: [], domains: [] }
      return { commit: false, value: snapshotReview(snapshot, actor, environment, source.value.evidence, binding) }
    }, { signal: request.signal })
    const before = await snapshotRead()
    if (before.status !== "ok") return before
    const after = await snapshotRead()
    if (!await input.host.revalidate(binding) || request.signal.aborted || input.host.requestFor(binding) !== request || after.status === "denied") return { status: "denied" as const, reason: "current-authority-unavailable" }
    if (after.status !== "ok" || digestSfValue(after.value) !== digestSfValue(before.value)) return { status: "stale" as const, reason: "requisition-review-changed" }
    return before
  }
  const prepare = async (incoming: { review: ProcurementApprovalReview; action: ProcurementApprovalAction }, binding: TrustedDomainContext): Promise<PortResult<ProcurementApprovalPlan>> => {
    if (!approvalValue(incoming) || !exactKeys(incoming, ["review", "action"]) || !validApprovalReview(incoming.review) || !validApprovalAction(incoming.action)) return { status: "needs-input", reason: "explicit-requisition-action-required" }
    const selected = structuredClone(incoming)
    const current = await read(selected.review.source.refId, binding)
    if (current.status !== "ok") return current
    // This compares the reviewed CAS and holder, not just the amount. Never refresh a retained command silently.
    if (digestSfValue(current.value.review) !== digestSfValue(selected.review)) return { status: "stale", reason: "requisition-review-changed" }
    return approvalPlan(current.value, selected.action)
  }
  return {
    async review(sourceRef: string, binding: TrustedDomainContext): Promise<PortResult<ProcurementApprovalReview>> {
      const current = await read(sourceRef, binding)
      return current.status === "ok" ? { status: "ok", value: structuredClone(current.value.review) } : current
    },
    prepare,
    async admission(incoming: ProcurementApprovalPlan, binding: TrustedDomainContext): Promise<PortResult<ProcurementApprovalAdmission>> {
      if (!approvalValue(incoming) || !exactKeys(incoming, ["kind", "command", "review", "action", "requiresExplicitAction", "approvalGranted", "receipt"]) || incoming.kind !== "procurement-pr-lifecycle-v1" || incoming.requiresExplicitAction !== true || incoming.approvalGranted !== false || incoming.receipt !== null) return { status: "needs-input", reason: "explicit-requisition-plan-required" }
      const selected = structuredClone(incoming)
      const prepared = await prepare({ review: selected.review, action: selected.action }, binding)
      if (prepared.status !== "ok") return prepared
      if (digestSfValue(prepared.value) !== digestSfValue(selected)) return { status: "denied", reason: "requisition-command-mismatch" }
      const request = input.host.requestFor(binding)
      if (!request || request.method !== "POST" || request.signal.aborted || !await input.host.revalidate(binding) || input.host.requestFor(binding) !== request) return { status: "denied", reason: "current-authority-unavailable" }
      let finished = false
      return { status: "ok", value: {
        current(snapshot, actor, command, environment) {
          if (finished || request.signal.aborted || input.host.requestFor(binding) !== request) return { status: "denied", reason: "current-authority-unavailable" }
          if (!approvalValue(command) || digestSfValue(command) !== digestSfValue(selected.command)) return { status: "denied", reason: "requisition-command-mismatch" }
          const current = snapshotReview(snapshot, actor, environment, selected.review.source, binding)
          if (current.status !== "ok") return current
          if (digestSfValue(current.value.review) !== digestSfValue(selected.review)) return { status: "stale", reason: "requisition-review-changed" }
          const plan = approvalPlan(current.value, selected.action)
          if (plan.status !== "ok") return plan
          if (digestSfValue(plan.value) !== digestSfValue(selected)) return { status: "stale", reason: "requisition-plan-changed" }
          finished = true
          return { status: "ok", value: true }
        },
        finish() { finished = true },
      } }
    },
  }
}

function approvalPlan(current: { review: ProcurementApprovalReview; requisition: Record<string, unknown> }, action: ProcurementApprovalAction): PortResult<ProcurementApprovalPlan> {
  const review = current.review
  if (!review.allowedActions.includes(action.kind)) return { status: "denied", reason: "requisition-action-unavailable" }
  if (action.kind === "save-estimate" && action.amount === review.amount) return { status: "needs-input", reason: "requisition-already-matches" }
  if (action.kind !== "save-estimate" && action.amount !== review.amount) return { status: "needs-input", reason: "requisition-amount-mismatch" }
  if (action.kind === "submit-current" && validatePR(current.requisition as Parameters<typeof validatePR>[0]).length) return { status: "needs-input", reason: "requisition-fields-incomplete" }
  if ((action.kind === "approve-submitted" || action.kind === "reject-submitted") && (review.submittedAmount !== action.amount || review.submittedCurrency !== review.currency || review.holderId !== action.holderId)) return { status: "needs-input", reason: "submitted-snapshot-mismatch" }
  const command: Command = {
    page: "Requests", id: review.source.target.recordId, version: review.domainVersion, confirmed: false,
    action: action.kind === "save-estimate" ? "save" : action.kind === "submit-current" ? "submit_pr" : action.kind === "approve-submitted" ? "approve" : "reject",
    values: action.kind === "save-estimate" ? { pr: { estAmount: action.amount } } : action.kind === "submit-current" ? {} : action.kind === "approve-submitted" ? { comment: action.comment } : { reason: action.reason },
  }
  return { status: "ok", value: { kind: "procurement-pr-lifecycle-v1", command, review: structuredClone(review), action: structuredClone(action), requiresExplicitAction: true, approvalGranted: false, receipt: null } }
}

function finiteApprovalAmount(value: unknown) {
  return typeof value === "number" && Number.isFinite(value) ? value : null
}

function validApprovalAction(action: ProcurementApprovalAction) {
  if (!action || typeof action !== "object" || typeof action.amount !== "number" || !Number.isFinite(action.amount) || action.amount < 0) return false
  const keys = Object.keys(action).sort()
  if (action.kind === "save-estimate" || action.kind === "submit-current") return digestSfValue(keys) === digestSfValue(["amount", "kind"])
  if (action.kind !== "approve-submitted" && action.kind !== "reject-submitted") return false
  if (action.holderId !== null && (typeof action.holderId !== "string" || !action.holderId.trim())) return false
  if (action.kind === "approve-submitted") return typeof action.comment === "string" && digestSfValue(keys) === digestSfValue(["amount", "comment", "holderId", "kind"])
  return typeof action.reason === "string" && !!action.reason.trim() && digestSfValue(keys) === digestSfValue(["amount", "holderId", "kind", "reason"])
}

function exactKeys(value: unknown, keys: readonly string[]) {
  return !!value && typeof value === "object" && !Array.isArray(value) && digestSfValue(Object.keys(value).sort()) === digestSfValue([...keys].sort())
}

function validApprovalReview(review: ProcurementApprovalReview) {
  if (!exactKeys(review, ["kind", "source", "domainVersion", "stage", "amount", "currency", "submittedAmount", "submittedCurrency", "holderId", "allowedActions", "authorityDigest", "recordDigest", "policyDigest"])) return false
  if (review.kind !== "procurement-pr-review-v1" || !Number.isSafeInteger(review.domainVersion) || review.domainVersion < 0 || typeof review.stage !== "string" || !/^[A-Z]{3}$/.test(review.currency)) return false
  const source = review.source
  if (!source || source.kind !== "record" || source.schema !== "sf-evidence-v1" || typeof source.refId !== "string" || !source.refId || !source.target || source.target.surface !== "procurement" || source.target.recordType !== "procurement-request") return false
  if (![review.amount, review.submittedAmount].every((value) => value === null || typeof value === "number" && Number.isFinite(value))) return false
  if (review.submittedCurrency !== null && (typeof review.submittedCurrency !== "string" || !/^[A-Z]{3}$/.test(review.submittedCurrency))) return false
  if (review.holderId !== null && (typeof review.holderId !== "string" || !review.holderId.trim())) return false
  return Array.isArray(review.allowedActions) && review.allowedActions.every((value) => ["save-estimate", "submit-current", "approve-submitted", "reject-submitted"].includes(value)) && [review.authorityDigest, review.recordDigest, review.policyDigest].every((value) => typeof value === "string" && /^[a-f0-9]{64}$/.test(value))
}

// A malformed transport object must be refused before cloning, hashing or reading its fields.
function approvalValue(value: unknown, active = new WeakSet<object>(), depth = 0): boolean {
  if (depth > 24) return false
  if (value === null || typeof value === "string" || typeof value === "boolean") return true
  if (typeof value === "number") return Number.isFinite(value)
  if (!value || typeof value !== "object" || active.has(value) || (!Array.isArray(value) && ![Object.prototype, null].includes(Object.getPrototypeOf(value))) || Object.getOwnPropertySymbols(value).length) return false
  active.add(value)
  const descriptors = Object.getOwnPropertyDescriptors(value)
  const valid = Object.values(descriptors).every((entry) => "value" in entry && approvalValue(entry.value, active, depth + 1))
  active.delete(value)
  return valid
}

import type { Application } from "../../runtime/application.ts"
import { roleMap } from "../../runtime/admin.ts"
import { object, rows } from "../../runtime/contract.ts"
import { domain } from "../../runtime/procurement.ts"
import { digestSfValue } from "../contracts/canonical.ts"
import type { Period } from "../contracts/context.ts"
import type { DomainPortHost } from "../contracts/ports.ts"
import type { TrustedUiContext } from "../contracts/sf-execution.ts"
import type { createSfUiAuthority } from "../integration/ui-authority.ts"
import type { createProcurementPort } from "./port.ts"
import { createProcurementQueueView } from "./queue-view.ts"
import { digestProcurementSource } from "./sources.ts"
import type { createProcurementCollectionRegistry } from "./sources.ts"

export const procurementQueueIntent = (period: Period) => ({ requestRef: `sf-procurement-queue-view:${period.start}:${period.end}` })

/** Prepare outside the page lock; recheck the very same C02 selection inside its authorized transaction. */
export function createProcurementQueuePageView(input: {
  host: DomainPortHost
  ui: ReturnType<typeof createSfUiAuthority>
  collection: ReturnType<typeof createProcurementCollectionRegistry>
  port: Pick<ReturnType<typeof createProcurementPort>, "list">
  selectPeriod: (context: TrustedUiContext, period: Period) => Promise<(() => void) | undefined>
}): NonNullable<Application["productView"]> {
  return async (request, surface, page) => {
    // The unchanged default Procurement page is Dashboard, which needs no queue admission.
    if (surface !== "procurement" || !["GET", "HEAD"].includes(request.method) || page !== "Requests" && page !== "My approvals") return undefined
    const failure = (status: string) => Response.json({ status, reason: "procurement-queue-unavailable" }, { status: status === "denied" ? 403 : status === "stale" ? 409 : 503, headers: { "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" } })
    const environment = await input.host.environment(request)
    const year = new Date(environment.at).getUTCFullYear()
    if (!Number.isSafeInteger(year) || year < 1 || year > 9999) return failure("unavailable")
    const period = { start: `${String(year).padStart(4, "0")}-01-01`, end: `${String(year).padStart(4, "0")}-12-31` }
    const digest = digestSfValue(procurementQueueIntent(period))
    const admission = await input.ui.admit(request, "sf_request_read", digest)
    if (admission.status !== "ok") return failure(admission.status)
    const context = admission.value
    let retained = false
    let selectionRef: string | undefined
    let releasePeriod: (() => void) | undefined
    const finish = () => {
      if (selectionRef) input.collection.releaseSelection(selectionRef)
      releasePeriod?.()
      input.ui.finish(context)
    }
    try {
      if (!await input.ui.validate(context, "sf_request_read", digest)) return failure("denied")
      releasePeriod = await input.selectPeriod(context, period)
      if (!releasePeriod) return failure("denied")
      const selected = await input.collection.createSelection(context)
      if (selected.status !== "ok") return failure(selected.status)
      selectionRef = selected.value
      const selection = await input.collection.resolveRequestCollection(selected.value, context)
      if (selection.status !== "ok") return failure(selection.status)
      const projected = await input.port.list(selected.value, context)
      if (projected.status !== "ok") return failure(projected.status)
      const presentation = createProcurementQueueView(projected.value)
      if (!presentation || !await input.ui.revalidate(context)) return failure("unavailable")
      const selectedScope = selection.value
      retained = true
      return {
        data: { procurementQueueView: presentation },
        current: async (snapshot, actor) => {
          if (actor.id !== context.binding.principalRef || !await input.ui.revalidate(context) ||
            !input.collection.isCurrentRequestCollection(snapshot, selectedScope.selection, selectedScope.requests, selectedScope.statusSelections)) return false
          const scopes = Object.values(snapshot.sfSources?.scopes ?? {}).filter((entry) => entry.alive && entry.incarnation === selectedScope.selection.target.incarnation && entry.version === selectedScope.selection.target.version && entry.scope.recordType === "procurement-request-selection")
          if (scopes.length !== 1) return false
          const selector = object(scopes[0]!.scope.selector)
          if (!Array.isArray(selector.roles) || digestSfValue([...selector.roles].sort()) !== digestSfValue([...actor.roles].sort()) || selector.canWrite !== actor.canWrite || selector.roleMapDigest !== digestSfValue(roleMap(snapshot, "procurement"))) return false
          const current = domain.view(snapshot, actor, environment)
          const records = rows(current.data.requests)
          if (object(current.data.formSettings).currency !== selectedScope.context.currency || records.length !== presentation.rows.length ||
            selectedScope.requests.some((evidence) => !input.collection.isCurrentRequestSource(snapshot, evidence) ||
              records.filter((record) => record.number === evidence.target.recordId).length !== 1 ||
              digestProcurementSource(records.find((record) => record.number === evidence.target.recordId), current.data.formSettings) !== evidence.target.projectionDigest)) return false
          return !request.signal.aborted && await input.ui.revalidate(context)
        },
        finish,
      }
    } finally {
      if (!retained) finish()
    }
  }
}

import { digestSfValue } from "../contracts/canonical.ts"
import type { BusinessEvidenceRef } from "../contracts/business-context.ts"
import type { DecisionCase, PreparedChange } from "../contracts/decisions.ts"
import type { CommandReceipt } from "../contracts/context.ts"
import type { DomainPortHost, PortResult, PreparedApplyPort } from "../contracts/ports.ts"
import type { TrustedDomainContext } from "../contracts/sf-execution.ts"
import type { SfProductState, SfProductStatePort, SfStateResult } from "../contracts/state.ts"
import { caseApplicationState, reconcileDomainReceipt } from "./receipts.ts"
import { isReviewDigest, preparedOriginalIntent, preparedOriginalIntentState, receiptProofMatches, receiptProofTransactionKey, receiptReviewBinding, type PreparedApplyRequest, type ReviewDigestFor } from "./receipt-review-binding.ts"
import { applicationAttempt, applicationAttemptKey, applicationAttempts } from "./application-attempt.ts"

/** Explicit human application; each domain commits its own receipt before the case is reconciled. */
export function createPreparedExecution(input: {
  state: SfProductStatePort
  host: Pick<DomainPortHost, "requestFor" | "revalidate">
  apply: PreparedApplyPort
  authorizeCase: (value: DecisionCase, context: TrustedDomainContext) => Promise<boolean>
  authorizeApplication: (request: { caseRef: { id: string; incarnation: string; version: number }; changeId: string; choiceId: string }, change: PreparedChange, context: TrustedDomainContext) => Promise<boolean>
  confirmApplication: (request: { caseRef: { id: string; incarnation: string; version: number }; changeId: string; choiceId: string }, context: TrustedDomainContext) => Promise<boolean>
  operationIdentity: (context: TrustedDomainContext) => string | undefined
  classifyReceipt: (receipt: CommandReceipt, change: PreparedChange, context: TrustedDomainContext) => Promise<{ state: "applied" | "awaiting-approval" | "conflict" | "failed" | "cancelled"; evidence: Extract<BusinessEvidenceRef, { kind: "receipt" }> } | undefined>
  reviewDigestFor: ReviewDigestFor
  revalidateProducer: (request: { caseRef: { id: string; incarnation: string; version: number }; changeId: string; choiceId: string }, context: TrustedDomainContext) => Promise<PortResult<{ reviewDigest: string }>>
}) {
  return async (incoming: { caseRef: { id: string; incarnation: string; version: number }; changeId: string; choiceId: string }, context: TrustedDomainContext, mode: "apply" | "recover" = "apply"): Promise<PortResult<CommandReceipt>> => {
    const request = structuredClone(incoming)
    const source = input.host.requestFor(context)
    const operation = input.operationIdentity(context)
    if (context.kind !== "ui" || !source || !operation || !await input.host.revalidate(context)) return { status: "denied", reason: "human-authority-required" }
    const current = await input.state.read(source, "cases", (state, authority) => authority.principalRef === context.binding.principalRef && authority.policyVersion === context.binding.policyVersion && authority.accessRevision === context.binding.accessRevision ? state.cases[request.caseRef.id] : undefined)
    if (current.status !== "ok") return failure(current)
    const value = current.value
    if (!value || value.incarnation !== request.caseRef.incarnation || !value.participants.includes(context.binding.principalRef) || !await input.authorizeCase(value, context)) return { status: "denied", reason: "case-access-unavailable" }
    const selectedChanges = value.preparedChanges.filter((item) => item.id === request.changeId)
    const change = selectedChanges[0]
    const choices = value.choices.filter((choice) => choice.id === request.choiceId)
    const choiceDigest = digestSfValue(choices)
    if (selectedChanges.length !== 1 || !change || change.choiceId !== request.choiceId || choices.length !== 1) return { status: "unavailable", reason: "prepared-change-unavailable" }
    if (value.version < request.caseRef.version) return { status: "stale", reason: "case-changed" }
    if (change.state !== "planned" && !change.receipt) return { status: "conflict", reason: "change-not-applicable" }
    if (!await input.authorizeApplication(request, change, context).catch(() => false)) return { status: "denied", reason: "application-authority-unavailable" }
    const lookup = structuredClone(await callDomain(() => input.apply.readReceipt({ surface: change.target.surface, targetRef: change.target.id, targetIncarnation: change.target.incarnation, idempotencyKey: change.idempotencyKey, commandDigest: change.operation.commandDigest }, context)))
    if (lookup.status !== "ok") return lookup
    // Historical admission can only reconcile an existing domain receipt.
    if (mode === "recover" && lookup.value.state !== "found") return { status: "unavailable", reason: "original-receipt-unavailable" }
    const reviewDigest = input.reviewDigestFor(context, request, change)
    if (!isReviewDigest(reviewDigest)) return { status: "needs-input", reason: "review-proof-required" }
    const retainReceipt = async (expectedCase: DecisionCase, receipt: CommandReceipt) => {
      if (expectedCase.preparedChanges.filter((item) => item.receipt?.id === receipt.id).length !== 1 || expectedCase.preparedChanges.find((item) => item.receipt?.id === receipt.id)?.id !== change.id || expectedCase.receipts.filter((item) => item.id === receipt.id).length !== 1 || digestSfValue(expectedCase.receipts.find((item) => item.id === receipt.id)) !== digestSfValue(receipt)) return false
      // This is a consistency fence for a receipt already authorized by its
      // canonical reader, never a substitute for that reader's authority.
      const retained = await input.state.read(source, "cases", (state, authority) => authority.principalRef === context.binding.principalRef && authority.policyVersion === context.binding.policyVersion && authority.accessRevision === context.binding.accessRevision && !!state.cases[expectedCase.id] && digestSfValue(state.cases[expectedCase.id]) === digestSfValue(expectedCase) && receiptSnapshotMatches(state, request, change, receipt, reviewDigest, context)).catch(() => undefined)
      return input.host.requestFor(context) === source && !source.signal.aborted && retained?.status === "ok" && retained.value
    }
    if (lookup.value.state === "found") {
      const bound = await input.state.read(source, "receipts", (state, authority) => authority.principalRef === context.binding.principalRef && authority.policyVersion === context.binding.policyVersion && authority.accessRevision === context.binding.accessRevision ? {
        proof: state.transactions[receiptProofTransactionKey(authority.principalRef, change.target.id, change.idempotencyKey)],
        intent: preparedOriginalIntentState(state, request, change, state.cases[request.caseRef.id]?.choices.filter((choice) => choice.id === request.choiceId) ?? [], reviewDigest, context, applicationAttempts(state, request)),
      } : undefined).catch(() => undefined)
      if (!bound || bound.status !== "ok" || !bound.value?.proof) return { status: "unavailable", reason: "review-proof-unbound" }
      if (bound.value.proof.commandDigest !== receiptReviewBinding(change, reviewDigest) || digestSfValue(bound.value.proof.value) !== digestSfValue(lookup.value.receipt)) return { status: "conflict", reason: "review-proof-mismatch" }
      if (bound.value.intent !== "matched") return { status: bound.value.intent === "missing" ? "unavailable" : "conflict", reason: bound.value.intent === "missing" ? "original-intent-unverifiable" : "original-intent-mismatch" }
      if (change.receipt) {
        if (digestSfValue(change.receipt) !== digestSfValue(lookup.value.receipt)) return { status: "unavailable", reason: "receipt-identity-collision" }
        if (!await input.host.revalidate(context) || !await input.authorizeCase(value, context).catch(() => false) || !await input.authorizeApplication(request, change, context).catch(() => false)) return { status: "denied", reason: "case-access-unavailable" }
        if (!await retainReceipt(value, lookup.value.receipt)) return { status: "unavailable", reason: "receipt-authority-changed" }
        return { status: "ok", value: lookup.value.receipt }
      }
    }
    if (!await input.host.revalidate(context) || !await input.authorizeCase(value, context)) return { status: "denied", reason: "case-access-unavailable" }
    if (lookup.value.state === "not-found" && change.receipt) return { status: "unavailable", reason: "authoritative-receipt-unavailable" }
    if (lookup.value.state === "not-found") {
      const attempted = await input.state.read(source, "cases", (state, authority) => authority.principalRef === context.binding.principalRef && authority.policyVersion === context.binding.policyVersion && authority.accessRevision === context.binding.accessRevision ? applicationAttempts(state, request).length > 0 : undefined).catch(() => undefined)
      if (!attempted || attempted.status !== "ok" || attempted.value === undefined) return { status: "unavailable", reason: "application-attempt-unavailable" }
      if (attempted.value) return { status: "unavailable", reason: "application-indeterminate-reconciliation-required" }
      if (value.version !== request.caseRef.version) return { status: "stale", reason: "case-changed" }
      const proof = await input.revalidateProducer(request, context).catch(() => undefined)
      if (!proof || proof.status !== "ok" || proof.value.reviewDigest !== reviewDigest) return proof && proof.status !== "ok" ? proof : { status: proof ? "stale" : "unavailable", reason: proof ? "review-proof-mismatch" : "review-producer-unavailable" }
      if (!await input.confirmApplication(request, context).catch(() => false)) return { status: "denied", reason: "application-confirmation-required" }
      const latest = await input.state.read(source, "cases", (state, authority) => authority.principalRef === context.binding.principalRef && authority.policyVersion === context.binding.policyVersion && authority.accessRevision === context.binding.accessRevision ? state.cases[request.caseRef.id] : undefined).catch(() => undefined)
      if (!latest || latest.status !== "ok") return { status: "unavailable", reason: "case-unavailable" }
      const fresh = latest.value
      const currentChange = fresh?.preparedChanges.find((item) => item.id === change.id && item.choiceId === request.choiceId)
      if (!fresh || fresh.incarnation !== value.incarnation || fresh.version !== value.version || !fresh.participants.includes(context.binding.principalRef) || fresh.preparedChanges.filter((item) => item.id === change.id).length !== 1 || digestSfValue(fresh.choices.filter((choice) => choice.id === request.choiceId)) !== choiceDigest || !currentChange || currentChange.state !== "planned" || digestSfValue(currentChange) !== digestSfValue(change)) return { status: "stale", reason: "case-changed" }
      if (!await input.authorizeCase(fresh, context).catch(() => false) || !await input.authorizeApplication(request, currentChange, context).catch(() => false) || !await input.host.revalidate(context).catch(() => false)) return { status: "denied", reason: "application-authority-unavailable" }
      const attempt = { ...applicationAttempt(request, currentChange, reviewDigest, context.binding.principalRef, operation), originalIntent: preparedOriginalIntent(request, currentChange, fresh.choices.filter((choice) => choice.id === request.choiceId)[0]!, reviewDigest, context) }
      // Persist before crossing the domain boundary. A crash before dispatch is
      // conservatively unresolved; absence of a receipt never grants a new dispatch.
      const reservation = { createdHere: false }
      const reserved = await input.state.transaction<typeof attempt | null>(source, { namespace: "cases", expectedStorageVersion: latest.storageVersion, targetRef: value.id, targetIncarnation: value.incarnation, idempotencyKey: applicationAttemptKey(request), commandDigest: digestSfValue(attempt) }, async (state, authority) => {
        const actual = state.cases[value.id]
        if (!actual || digestSfValue(actual) !== digestSfValue(fresh) || authority.principalRef !== context.binding.principalRef || authority.policyVersion !== context.binding.policyVersion || authority.accessRevision !== context.binding.accessRevision || applicationAttempts(state, request).length) return { commit: false, value: null }
        // A provider may return a prior transaction without invoking this callback.
        // Only this invocation's successful commit may perform the first dispatch.
        reservation.createdHere = true
        return { commit: true, value: attempt }
      }).catch(() => undefined)
      if (!reserved || reserved.status !== "ok" || !reserved.value || !reservation.createdHere) {
        const recorded = await input.state.read(source, "cases", (state, authority) => authority.principalRef === context.binding.principalRef && authority.policyVersion === context.binding.policyVersion && authority.accessRevision === context.binding.accessRevision ? applicationAttempts(state, request).length > 0 : undefined).catch(() => undefined)
        return { status: "unavailable", reason: recorded?.status === "ok" && recorded.value ? "application-indeterminate-reconciliation-required" : "application-attempt-unavailable" }
      }
      if (source.signal.aborted || !await input.host.revalidate(context).catch(() => false)) return { status: "unavailable", reason: "application-indeterminate-reconciliation-required" }
    }
    const observed = structuredClone(lookup.value.state === "found" ? { status: "ok" as const, value: lookup.value.receipt } : await callDomain(() => input.apply.executePrepared(request, context)))
    if (observed.status !== "ok") return observed
    const result = structuredClone(await input.classifyReceipt(structuredClone(observed.value), structuredClone(change), context).catch(() => undefined))
    if (!result || !await input.host.revalidate(context)) return { status: "unavailable", reason: "receipt-classification-unavailable" }
    if (result.evidence.installationId !== context.binding.installationId || result.evidence.projectId !== context.binding.projectId || result.evidence.target.surface !== observed.value.surface || result.evidence.target.receiptId !== observed.value.id || result.evidence.target.idempotencyKey !== observed.value.idempotencyKey || result.evidence.target.targetIncarnation !== observed.value.targetIncarnation || result.evidence.target.commandDigest !== observed.value.commandDigest || result.evidence.target.version !== observed.value.version) return { status: "unavailable", reason: "receipt-evidence-mismatch" }
    const priorReceipt = value.receipts.find((receipt) => receipt.id === observed.value.id)
    if (value.preparedChanges.some((item) => item.id !== change.id && item.receipt?.id === observed.value.id)) return { status: "unavailable", reason: "receipt-identity-collision" }
    if (priorReceipt && digestSfValue(priorReceipt) !== digestSfValue(observed.value)) return { status: "unavailable", reason: "receipt-identity-collision" }
    const reconciled = reconcileDomainReceipt({ change, receipt: observed.value, principalRef: context.binding.principalRef, state: result.state })
    if (reconciled.status !== "ok") return reconciled
    if (change.receipt) {
      if (!await input.authorizeCase(value, context).catch(() => false) || !await input.authorizeApplication(request, change, context).catch(() => false) || !await input.host.revalidate(context).catch(() => false)) return { status: "denied", reason: "case-access-unavailable" }
      if (!await retainReceipt(value, observed.value)) return { status: "unavailable", reason: "receipt-authority-changed" }
      return { status: "ok", value: observed.value }
    }
    // The producer may have advanced the cases namespace while committing its receipt.
    // Reopen it after the domain result and preserve unrelated, versioned case edits.
    const reconciliation = await input.state.read(source, "cases", (state, authority) => authority.principalRef === context.binding.principalRef && authority.policyVersion === context.binding.policyVersion && authority.accessRevision === context.binding.accessRevision ? state.cases[value.id] : undefined).catch(() => undefined)
    // Fresh storage may preserve unrelated edits, but cannot bind the original
    // receipt to a materially replaced or duplicated historical choice.
    if (reconciliation?.status === "ok" && reconciliation.value && digestSfValue(reconciliation.value.choices.filter((choice) => choice.id === request.choiceId)) !== choiceDigest) return { status: "stale", reason: "prepared-choice-changed" }
    if (reconciliation?.status === "ok" && reconciliation.value && reconciliation.value.preparedChanges.filter((item) => item.id === change.id).length !== 1) return { status: "stale", reason: "prepared-change-changed" }
    if (!reconciliation || reconciliation.status !== "ok" || !reconciliation.value) return { status: "unavailable", reason: "case-reconciliation-pending" }
    const fresh = reconciliation.value
    const selected = fresh.preparedChanges.find((item) => item.id === change.id && item.choiceId === request.choiceId)
    if (fresh.incarnation !== value.incarnation || fresh.version < value.version || !fresh.participants.includes(context.binding.principalRef) || !fresh.choices.some((choice) => choice.id === request.choiceId) || !selected || !await input.authorizeCase(fresh, context).catch(() => false) || !await input.authorizeApplication(request, selected, context).catch(() => false) || !await input.host.revalidate(context).catch(() => false)) return { status: "denied", reason: "case-access-unavailable" }
    // Re-observe the domain's authoritative receipt after the asynchronous case
    // callbacks. The earlier command response is not a durable receipt fence.
    const confirmedReceipt = structuredClone(await callDomain(() => input.apply.readReceipt({ surface: change.target.surface, targetRef: change.target.id, targetIncarnation: change.target.incarnation, idempotencyKey: change.idempotencyKey, commandDigest: change.operation.commandDigest }, context)))
    if (confirmedReceipt.status !== "ok") return confirmedReceipt
    if (confirmedReceipt.value.state !== "found" || digestSfValue(confirmedReceipt.value.receipt) !== digestSfValue(observed.value)) return { status: "unavailable", reason: "authoritative-receipt-changed" }
    if (source.signal.aborted || !await input.authorizeCase(fresh, context).catch(() => false) || !await input.authorizeApplication(request, selected, context).catch(() => false) || !await input.host.revalidate(context).catch(() => false)) return { status: "denied", reason: "case-access-unavailable" }
    if (selected.receipt) {
      if (digestSfValue(selected) !== digestSfValue(reconciled.change)) return { status: "unavailable", reason: "receipt-identity-collision" }
      if (!await retainReceipt(fresh, observed.value)) return { status: "unavailable", reason: "receipt-authority-changed" }
      return { status: "ok", value: observed.value }
    }
    if (digestSfValue(selected) !== digestSfValue(change)) return { status: "stale", reason: "prepared-change-changed" }
    if (fresh.preparedChanges.some((item) => item.id !== change.id && item.receipt?.id === observed.value.id) || fresh.receipts.some((receipt) => receipt.id === observed.value.id && digestSfValue(receipt) !== digestSfValue(observed.value))) return { status: "unavailable", reason: "receipt-identity-collision" }
    const changes = fresh.preparedChanges.map((item) => item.id === change.id ? reconciled.change : item)
    const reconciledCase: DecisionCase = { ...fresh, version: fresh.version + 1, preparedChanges: changes, receipts: fresh.receipts.some((receipt) => receipt.id === observed.value.id) ? fresh.receipts : [...fresh.receipts, observed.value], sourceRefs: [...fresh.sourceRefs, result.evidence].filter((ref, index, refs) => refs.findIndex((other) => other.refDigest === ref.refDigest) === index), state: caseApplicationState(changes) }
    const saved = await input.state.transaction(source, { namespace: "cases", expectedStorageVersion: reconciliation.storageVersion, targetRef: value.id, targetIncarnation: value.incarnation, idempotencyKey: `${operation}:${change.id}:${observed.value.id}`, commandDigest: digestSfValue({ caseRef: request.caseRef, changeId: change.id, receipt: observed.value, state: result.state, evidence: result.evidence }) }, async (state, authority) => {
      const actual = state.cases[value.id]
      if (!actual || digestSfValue(actual) !== digestSfValue(fresh) || authority.principalRef !== context.binding.principalRef || authority.policyVersion !== context.binding.policyVersion || authority.accessRevision !== context.binding.accessRevision || !receiptSnapshotMatches(state, request, change, observed.value, reviewDigest, context)) return { commit: false, value: false }
      state.cases[value.id] = reconciledCase
      return { commit: true, value: true }
    }).catch(() => undefined)
    if (!saved || saved.status !== "ok") return { status: "unavailable", reason: "case-reconciliation-pending" }
    if (!saved.value) return { status: "unavailable", reason: "case-reconciliation-pending" }
    const currentReceipt = await input.classifyReceipt(structuredClone(observed.value), structuredClone(reconciled.change), context).catch(() => undefined)
    if (!currentReceipt || digestSfValue(currentReceipt) !== digestSfValue(result) || !await input.authorizeApplication(request, reconciled.change, context).catch(() => false) || !await input.host.revalidate(context).catch(() => false)) return { status: "unavailable", reason: "receipt-authority-changed" }
    if (!await retainReceipt(reconciledCase, observed.value)) return { status: "unavailable", reason: "receipt-authority-changed" }
    return { status: "ok", value: observed.value }
  }
}

function receiptSnapshotMatches(state: SfProductState, request: PreparedApplyRequest, change: PreparedChange, receipt: CommandReceipt, reviewDigest: string, context: TrustedDomainContext) {
  const proof = state.transactions[receiptProofTransactionKey(context.binding.principalRef, change.target.id, change.idempotencyKey)]
  const choices = state.cases[request.caseRef.id]?.choices.filter((choice) => choice.id === request.choiceId) ?? []
  return receiptProofMatches(state, change.target, receipt, context.binding.principalRef) && proof?.commandDigest === receiptReviewBinding(change, reviewDigest) &&
    preparedOriginalIntentState(state, request, change, choices, reviewDigest, context, applicationAttempts(state, request)) === "matched"
}

async function callDomain<T>(work: () => Promise<PortResult<T>>): Promise<PortResult<T>> {
  try {
    return await work()
  } catch {
    return { status: "unavailable", reason: "domain-result-unknown" }
  }
}

function failure(value: SfStateResult<unknown>): PortResult<never> {
  if ("reason" in value) return { status: value.status, reason: value.reason }
  return { status: "unavailable", reason: "case-reconciliation-pending" }
}

import { digestSfValue } from "../contracts/canonical.ts"
import type { CommandReceipt } from "../contracts/context.ts"
import type { DecisionCase, PreparedChange } from "../contracts/decisions.ts"
import type { DomainPortHost, PortResult, PreparedApplyPort, PreparedDomainMutation } from "../contracts/ports.ts"
import type { TrustedDomainContext } from "../contracts/sf-execution.ts"
import type { SfProductStatePort } from "../contracts/state.ts"
import type { Actor, Environment, Snapshot } from "../../runtime/contract.ts"
import { isReviewDigest, preparedOriginalIntentState, receiptProofKey, receiptProofMatches, receiptProofTransactionKey, receiptReviewBinding, type ReviewDigestFor } from "./receipt-review-binding.ts"
import { applicationAttempts } from "./application-attempt.ts"

/** The callbacks resolve current host authority and domain data; none are supplied by a capability caller. */
export function createSfPreparedApply(input: {
  state: SfProductStatePort
  host: Pick<DomainPortHost, "requestFor" | "revalidate">
  authorizeCase: (value: DecisionCase, context: TrustedDomainContext) => Promise<boolean>
  authorizeLookup: (request: Parameters<PreparedApplyPort["readReceipt"]>[0], context: TrustedDomainContext) => Promise<boolean>
  authorizeReceipt: (receipt: CommandReceipt, request: Parameters<PreparedApplyPort["readReceipt"]>[0], context: TrustedDomainContext) => Promise<boolean>
  confirmHuman: (request: Parameters<PreparedApplyPort["executePrepared"]>[0], change: PreparedChange, context: TrustedDomainContext) => Promise<boolean>
  resolveActor: (snapshot: Snapshot, context: TrustedDomainContext) => Actor | undefined
  resolveMutation: (snapshot: Snapshot, change: PreparedChange, actor: Actor, context: TrustedDomainContext) => PreparedDomainMutation | undefined
  verifyGrant: (snapshot: Snapshot, request: Parameters<PreparedApplyPort["executePrepared"]>[0], change: PreparedChange, actor: Actor, context: TrustedDomainContext) => boolean
  receiptVersion: (snapshot: Snapshot, change: PreparedChange, actor: Actor) => number | undefined
  environment: (context: TrustedDomainContext) => Environment
  createId: () => string
  now: () => string
  reviewDigestFor: ReviewDigestFor
}): PreparedApplyPort {
  const port: PreparedApplyPort = {
    readReceipt: async (incoming, context) => {
      const request = structuredClone(incoming)
      const source = input.host.requestFor(context)
      if (!source || !await input.host.revalidate(context).catch(() => false) || !await input.authorizeLookup(request, context).catch(() => false)) return { status: "denied", reason: "invalid-authority" }
      const current = await input.state.read(source, "receipts", (state, authority) => {
        if (!sameAuthority(authority, context)) return undefined
        return Object.values(state.receipts).filter((item) => item.surface === request.surface && item.targetIncarnation === request.targetIncarnation && item.idempotencyKey === request.idempotencyKey && item.principalRef === context.binding.principalRef)
      }).catch(() => undefined)
      if (!current || current.status !== "ok" || !current.value) return { status: "unavailable", reason: "receipt-unavailable" }
      if (current.value.length > 1) return { status: "unavailable", reason: "receipt-identity-conflict" }
      const receipt = current.value[0]
      if (!receipt) {
        if (!await input.authorizeLookup(request, context).catch(() => false) || !await input.host.revalidate(context).catch(() => false)) return { status: "denied", reason: "invalid-authority" }
        return { status: "ok", value: { state: "not-found" } }
      }
      if (!await input.authorizeLookup(request, context).catch(() => false) || !await input.host.revalidate(context).catch(() => false)) return { status: "denied", reason: "receipt-access-unavailable" }
      if (receipt.commandDigest !== request.commandDigest) return { status: "conflict", reason: "idempotency-content-changed" }
      if (!await input.authorizeReceipt(receipt, request, context).catch(() => false) || !await input.host.revalidate(context).catch(() => false)) return { status: "denied", reason: "receipt-access-unavailable" }
      const retained = await input.state.read(source, "receipts", (state, authority) => sameAuthority(authority, context) && receiptProofMatches(state, { surface: request.surface, id: request.targetRef, incarnation: request.targetIncarnation }, receipt, authority.principalRef)).catch(() => undefined)
      if (retained?.status !== "ok" || !retained.value || source.signal.aborted || !input.host.requestFor(context)) return { status: "unavailable", reason: "authoritative-receipt-changed" }
      return { status: "ok", value: { state: "found", receipt: structuredClone(receipt) } }
    },
    executePrepared: async (incoming, context) => {
      const request = structuredClone(incoming)
      if (context.kind !== "ui") return { status: "denied", reason: "human-authority-required" }
      const source = input.host.requestFor(context)
      if (!source || !await input.host.revalidate(context).catch(() => false)) return { status: "denied", reason: "invalid-authority" }
      const current = await input.state.read(source, "cases", (state, authority) => sameAuthority(authority, context) ? state.cases[request.caseRef.id] : undefined).catch(() => undefined)
      if (!current || current.status !== "ok") return { status: "unavailable", reason: "case-unavailable" }
      const decision = current.value
      const changes = decision?.preparedChanges.filter((item) => item.id === request.changeId)
      const choices = decision?.choices.filter((choice) => choice.id === request.choiceId)
      const change = changes?.[0]
      if (!decision || decision.incarnation !== request.caseRef.incarnation || decision.version < request.caseRef.version || !decision.participants.includes(context.binding.principalRef) || choices?.length !== 1 || changes?.length !== 1 || !change || change.choiceId !== request.choiceId || (decision.version !== request.caseRef.version && !change.receipt)) return { status: "stale", reason: "case-changed" }
      if (!await input.authorizeCase(decision, context).catch(() => false) || !await input.host.revalidate(context).catch(() => false)) return { status: "denied", reason: "human-authority-required" }
      const reviewDigest = input.reviewDigestFor(context, request, change)
      if (!isReviewDigest(reviewDigest)) return { status: "needs-input", reason: "review-proof-required" }
      const binding = receiptReviewBinding(change, reviewDigest)
      const retainReceipt = async (receipt: CommandReceipt) => {
        const retained = await input.state.read(source, "receipts", (state, authority) => {
          const actual = state.cases[request.caseRef.id]
          const selected = actual?.preparedChanges.filter((item) => item.id === request.changeId)
          const attempts = applicationAttempts(state, request)
          return sameAuthority(authority, context) && !!actual && actual.incarnation === request.caseRef.incarnation && actual.version >= request.caseRef.version && actual.participants.includes(authority.principalRef) && selected?.length === 1 && selected[0]!.choiceId === request.choiceId &&
            (!selected[0]!.receipt || digestSfValue(selected[0]!.receipt) === digestSfValue(receipt)) && receiptProofMatches(state, change.target, receipt, authority.principalRef) &&
            state.transactions[receiptProofTransactionKey(authority.principalRef, change.target.id, change.idempotencyKey)]?.commandDigest === binding &&
            (!attempts.length || preparedOriginalIntentState(state, request, selected[0]!, actual.choices.filter((choice) => choice.id === request.choiceId), reviewDigest, context, attempts) === "matched")
        }).catch(() => undefined)
        return retained?.status === "ok" && retained.value && !source.signal.aborted && !!input.host.requestFor(context)
      }
      const recorded = await input.state.read(source, "receipts", (state, authority) => {
        if (!sameAuthority(authority, context)) return undefined
        const prior = state.transactions[receiptProofTransactionKey(authority.principalRef, change.target.id, change.idempotencyKey)]
        const matching = Object.values(state.receipts).filter((item) => item.surface === change.target.surface && item.idempotencyKey === change.idempotencyKey && item.targetIncarnation === change.target.incarnation && item.principalRef === authority.principalRef)
        const attempts = applicationAttempts(state, request)
        return { prior, matching, intent: attempts.length ? preparedOriginalIntentState(state, request, change, choices, reviewDigest, context, attempts) : undefined }
      }).catch(() => undefined)
      if (!recorded || recorded.status !== "ok" || !recorded.value || recorded.value.matching.length > 1) return { status: "unavailable", reason: "receipt-unavailable" }
      if (recorded.value.intent && recorded.value.intent !== "matched") return { status: recorded.value.intent === "missing" ? "unavailable" : "conflict", reason: recorded.value.intent === "missing" ? "original-intent-unverifiable" : "original-intent-mismatch" }
      const prior = recorded.value.prior
      const stored = recorded.value.matching[0]
      if (prior && prior.commandDigest !== binding) return { status: "conflict", reason: "idempotency-content-changed" }
      if (prior && stored && digestSfValue(prior.value) === digestSfValue(stored)) {
        if (change.receipt && digestSfValue(change.receipt) !== digestSfValue(stored)) return { status: "unavailable", reason: "receipt-identity-collision" }
        if (!await input.authorizeReceipt(stored, { surface: change.target.surface, targetRef: change.target.id, targetIncarnation: change.target.incarnation, idempotencyKey: change.idempotencyKey, commandDigest: change.operation.commandDigest }, context).catch(() => false) || !await input.host.revalidate(context).catch(() => false)) return { status: "denied", reason: "receipt-access-unavailable" }
        if (!await retainReceipt(stored)) return { status: "unavailable", reason: "receipt-authority-changed" }
        return { status: "ok", value: structuredClone(stored) }
      }
      if (prior || stored) return { status: "unavailable", reason: "review-proof-unbound" }
      if (change.receipt) return { status: "unavailable", reason: "authoritative-receipt-unavailable" }
      if (!await input.confirmHuman(request, change, context).catch(() => false)) return { status: "denied", reason: "human-authority-required" }
      if (change.state !== "planned") return { status: "conflict", reason: "change-not-applicable" }
      const receipts = await input.state.read(source, "receipts", (_state, authority) => sameAuthority(authority, context)).catch(() => undefined)
      if (!receipts || receipts.status !== "ok" || !receipts.value) return { status: "unavailable", reason: "receipt-unavailable" }
      const id = input.createId()
      if (!id.trim()) return { status: "unavailable", reason: "receipt-identity-unavailable" }
      const applied = await input.state.transaction<CommandReceipt | { existing: CommandReceipt } | { failure: "unavailable" | "conflict" } | null>(source, { namespace: "receipts", domainSurface: change.target.surface, expectedStorageVersion: receipts.storageVersion, additionalNamespaces: [{ namespace: "cases", expectedStorageVersion: current.storageVersion }], targetRef: change.target.id, targetIncarnation: change.target.incarnation, idempotencyKey: receiptProofKey(change.idempotencyKey), commandDigest: binding }, async (state, authority, snapshot) => {
        const actual = state.cases[request.caseRef.id]
        const selectedChanges = actual?.preparedChanges.filter((item) => item.id === request.changeId)
        const selected = selectedChanges?.[0]
        if (!sameAuthority(authority, context) || !actual || actual.incarnation !== decision.incarnation || actual.version !== decision.version || !actual.participants.includes(context.binding.principalRef) || selectedChanges?.length !== 1 || !selected || selected.choiceId !== request.choiceId || selected.state !== "planned" || digestSfValue(selected) !== digestSfValue(change) || digestSfValue(actual.choices.filter((choice) => choice.id === request.choiceId)) !== digestSfValue(choices)) return { commit: false, value: null }
        const attempts = applicationAttempts(state, request)
        if (attempts.length && preparedOriginalIntentState(state, request, selected, actual.choices.filter((choice) => choice.id === request.choiceId), reviewDigest, context, attempts) !== "matched") return { commit: false, value: null }
        const actor = input.resolveActor(snapshot, context)
        if (!actor || actor.id !== context.binding.principalRef || !input.verifyGrant(snapshot, request, selected, actor, context)) return { commit: false, value: null }
        const prior = Object.values(state.receipts).filter((item) => item.surface === selected.target.surface && item.idempotencyKey === selected.idempotencyKey && item.targetIncarnation === selected.target.incarnation && item.principalRef === actor.id)
        if (prior.length > 1) return { commit: false, value: { failure: "unavailable" as const } }
        if (prior[0]) return prior[0].commandDigest === selected.operation.commandDigest ? { commit: false, value: { existing: prior[0] } } : { commit: false, value: { failure: "conflict" as const } }
        const mutation = input.resolveMutation(snapshot, selected, actor, context)
        if (!mutation || mutation.surface !== selected.target.surface || mutation.targetIncarnation !== selected.target.incarnation || mutation.idempotencyKey !== selected.idempotencyKey || mutation.commandDigest !== selected.operation.commandDigest || mutation.expectedVersion !== selected.expectedVersion || selected.operation.expectedVersion !== selected.expectedVersion || selected.operation.command.version !== selected.expectedVersion || selected.operation.idempotencyKey !== selected.idempotencyKey || digestSfValue(selected.operation.target) !== digestSfValue(selected.target) || state.receipts[id]) return { commit: false, value: null }
        const staged = structuredClone(snapshot)
        const outcome = mutation.execute(staged, actor, input.environment(context))
        const status = outcome.value && typeof outcome.value === "object" && !Array.isArray(outcome.value) && "status" in outcome.value ? outcome.value.status : undefined
        if (!outcome.commit && status !== "conflict" && status !== "denied" && status !== "failed") return { commit: false, value: { failure: "unavailable" as const } }
        const target = outcome.commit ? staged : snapshot
        const version = input.receiptVersion(target, selected, actor)
        if (!Number.isSafeInteger(version) || version! < 0 || !input.verifyGrant(target, request, selected, actor, context)) return { commit: false, value: null }
        const result: CommandReceipt["result"] = outcome.commit ? { ok: true, value: outcome.value } : { ok: false, status: status === "conflict" ? 409 : status === "denied" ? 403 : 422, errors: ["domain-application-rejected"] }
        const receipt: CommandReceipt = { id, surface: mutation.surface, idempotencyKey: mutation.idempotencyKey, commandDigest: mutation.commandDigest, targetIncarnation: mutation.targetIncarnation, principalRef: actor.id, version: version!, result, at: input.now() }
        if (outcome.commit) Object.assign(snapshot, staged)
        state.receipts[id] = receipt
        return { commit: true, value: receipt }
      }).catch(() => undefined)
      if (applied?.status === "preview" && applied.value && "existing" in applied.value && applied.value.existing) {
        const receipt = applied.value.existing
        if (!await input.authorizeCase(decision, context).catch(() => false) || !await input.confirmHuman(request, change, context).catch(() => false) || !await input.authorizeReceipt(receipt, { surface: change.target.surface, targetRef: change.target.id, targetIncarnation: change.target.incarnation, idempotencyKey: change.idempotencyKey, commandDigest: change.operation.commandDigest }, context).catch(() => false) || !await input.host.revalidate(context).catch(() => false)) return { status: "denied", reason: "receipt-access-unavailable" }
        if (!await retainReceipt(receipt)) return { status: "unavailable", reason: "receipt-authority-changed" }
        return { status: "ok", value: receipt }
      }
      if (applied?.status === "preview" && applied.value && "failure" in applied.value && applied.value.failure) return { status: applied.value.failure, reason: "domain-application-rejected" }
      if (!applied || applied.status !== "ok" || !applied.value || "failure" in applied.value || "existing" in applied.value) return { status: applied?.status === "conflict" ? "conflict" : "unavailable", reason: "domain-application-unavailable" }
      if (!await input.authorizeCase(decision, context).catch(() => false) || !await input.confirmHuman(request, change, context).catch(() => false) || !await input.authorizeReceipt(applied.value, { surface: change.target.surface, targetRef: change.target.id, targetIncarnation: change.target.incarnation, idempotencyKey: change.idempotencyKey, commandDigest: change.operation.commandDigest }, context).catch(() => false) || !await input.host.revalidate(context).catch(() => false)) return { status: "unavailable", reason: "receipt-authority-changed" }
      if (!await retainReceipt(applied.value)) return { status: "unavailable", reason: "receipt-authority-changed" }
      return { status: "ok", value: applied.value }
    },
  }
  return port
}

function sameAuthority(authority: { principalRef: string; policyVersion: string; accessRevision: string }, context: TrustedDomainContext) {
  return authority.principalRef === context.binding.principalRef && authority.policyVersion === context.binding.policyVersion && authority.accessRevision === context.binding.accessRevision
}

import { digestSfValue } from "../contracts/canonical.ts"
import type { DecisionCase, PreparedChange } from "../contracts/decisions.ts"
import type { CommandReceipt } from "../contracts/context.ts"
import type { SfProductState } from "../contracts/state.ts"
import type { TrustedDomainContext } from "../contracts/sf-execution.ts"

export type PreparedApplyRequest = { caseRef: { id: string; incarnation: string; version: number }; changeId: string; choiceId: string }
export type ReviewDigestFor = (context: TrustedDomainContext, request: PreparedApplyRequest, change: PreparedChange) => string | undefined
export type AdmittedApply = PreparedApplyRequest & { reviewDigest: string }

export function isReviewDigest(value: string | undefined): value is string {
  return typeof value === "string" && /^[a-f0-9]{64}$/.test(value)
}
export function receiptProofKey(idempotencyKey: string) {
  return `prepared:${idempotencyKey}`
}
export function receiptProofTransactionKey(principalRef: string, targetId: string, idempotencyKey: string) {
  return JSON.stringify([principalRef, "receipts", targetId, receiptProofKey(idempotencyKey)])
}
export function receiptReviewBinding(change: PreparedChange, reviewDigest: string) {
  return digestSfValue({
    schema: "sf-receipt-review-binding-v1",
    reviewDigest,
    commandDigest: change.operation.commandDigest,
    idempotencyKey: change.idempotencyKey,
    surface: change.target.surface,
    targetId: change.target.id,
    targetIncarnation: change.target.incarnation,
  })
}
export function proposalReviewDigest(input: {
  caseId: string
  caseIncarnation: string
  changeCaseVersion: number
  choiceDigest: string
  change: PreparedChange
  fields: readonly { field: string; before: string | number | boolean | null; after: string | number | boolean | null; beforeCurrency?: string; afterCurrency?: string }[]
  sourceRefDigest: string
}) {
  return digestSfValue({
    schema: "sf-prepared-review-v1",
    caseId: input.caseId, caseIncarnation: input.caseIncarnation, changeCaseVersion: input.changeCaseVersion,
    choiceDigest: input.choiceDigest, changeId: input.change.id, choiceId: input.change.choiceId,
    expectedVersion: input.change.expectedVersion, idempotencyKey: input.change.idempotencyKey,
    commandDigest: input.change.operation.commandDigest, targetDigest: digestSfValue(input.change.target),
    requiredAuthority: [...input.change.requiredAuthority], fields: input.fields, sourceRefDigest: input.sourceRefDigest,
  })
}
export function sameApplyRequest(left: PreparedApplyRequest, right: PreparedApplyRequest) {
  return left.changeId === right.changeId && left.choiceId === right.choiceId && digestSfValue(left.caseRef) === digestSfValue(right.caseRef)
}

/** Retained inside the existing application attempt; canonical receipt proofs remain raw. */
export function preparedOriginalIntent(request: PreparedApplyRequest, change: PreparedChange, choice: DecisionCase["choices"][number], reviewDigest: string, context: TrustedDomainContext) {
  return {
    schema: "sf-prepared-original-intent-v1" as const,
    request: structuredClone(request),
    changeDigest: digestSfValue({ ...change, state: "planned", receipt: null }),
    choiceDigest: digestSfValue(choice),
    reviewBinding: receiptReviewBinding(change, reviewDigest),
    binding: {
      installationId: context.binding.installationId,
      projectId: context.binding.projectId,
      principalRef: context.binding.principalRef,
      policyVersion: context.binding.policyVersion,
      accessRevision: context.binding.accessRevision,
    },
  }
}

export function preparedOriginalIntentState(state: Readonly<SfProductState>, request: PreparedApplyRequest, change: PreparedChange, choices: readonly DecisionCase["choices"][number][], reviewDigest: string, context: TrustedDomainContext, entries: readonly SfProductState["transactions"][string][]) {
  if (!entries.length) return "missing"
  if (entries.length !== 1 || choices.length !== 1) return "mismatch"
  const proof = entries[0]!
  const attempt = proof.value
  if (!attempt || typeof attempt !== "object" || Array.isArray(attempt) || !("originalIntent" in attempt)) return "missing"
  const expected = preparedOriginalIntent(request, change, choices[0]!, reviewDigest, context)
  return proof.namespace === "cases" && proof.scopeDigest === digestSfValue(["cases"]) && proof.incarnation === state.incarnation &&
    proof.principalRef === context.binding.principalRef && proof.targetRef === request.caseRef.id && proof.targetIncarnation === request.caseRef.incarnation &&
    proof.commandDigest === digestSfValue(attempt) && digestSfValue(attempt.originalIntent) === digestSfValue(expected) ? "matched" : "mismatch"
}

/** Shared raw-receipt fence. The domain reader must still revalidate current access. */
export function receiptProofMatches(state: Readonly<SfProductState>, target: { surface: CommandReceipt["surface"]; id: string; incarnation: string }, receipt: CommandReceipt, principalRef: string) {
  const stored = state.receipts[receipt.id]
  const proof = state.transactions[receiptProofTransactionKey(principalRef, target.id, receipt.idempotencyKey)]
  const matches = Object.values(state.receipts).filter((item) => item.surface === target.surface && item.targetIncarnation === target.incarnation && item.idempotencyKey === receipt.idempotencyKey && item.principalRef === principalRef)
  const scope = target.surface === "dashboard" ? ["cases", "receipts"] : { namespaces: ["cases", "receipts"], domainSurface: target.surface }
  return matches.length === 1 && !!stored && !!proof && proof.namespace === "receipts" && proof.scopeDigest === digestSfValue(scope) &&
    proof.principalRef === principalRef && proof.targetRef === target.id && proof.targetIncarnation === target.incarnation && proof.incarnation === state.incarnation &&
    digestSfValue(stored) === digestSfValue(receipt) && digestSfValue(proof.value) === digestSfValue(receipt)
}

